from review import card,save,DATE
i='TCS-3917';_,c=card(i);refs=c['references'];refs[0]['year']=2019;refs[0]['locator']='IPEC 2018 proceedings published 5 February 2019; Sections 1–1.2, decision parameter and induced exclusion; Section 3, disjoint unions of cliques; Section 6, disjoint-union closure conjecture.'
refs += [dict(id='journal',title='Parameterized Complexity of Independent Set in H-Free Graphs',authors='Édouard Bonnet; Nicolas Bousquet; Pierre Charbit; Stéphan Thomassé; Rémi Watrigant',year=2020,url='https://doi.org/10.1007/s00453-020-00730-6',pdf_url='https://perso.ens-lyon.fr/edouard.bonnet/publi/pcMISHfreeJournal.pdf',locator='Algorithmica 82(8),2360–2394; published 17 June 2020. Author-hosted expanded manuscript, concluding section p. 33 lines 1185–1188 repeats this conjecture; Theorem 6 proves the cluster case.'),dict(id='later',title='When Maximum Stable Set Can Be Solved in FPT Time',authors='Édouard Bonnet; Nicolas Bousquet; Stéphan Thomassé; Rémi Watrigant',year=2019,url='https://doi.org/10.4230/LIPIcs.ISAAC.2019.49',pdf_url='https://drops.dagstuhl.de/storage/00lipics/lipics-vol149-isaac2019/LIPIcs.ISAAC.2019.49/LIPIcs.ISAAC.2019.49.pdf',locator='Published 28 November 2019; introduction and Section 5, including Theorem 29, distinguish deterministic tractable families from randomized algorithms for dart- and cricket-free graphs.')]
save(i,dict(title='Disjoint-union closure of tractable forbidden patterns',formal='For every pair of fixed nonempty finite simple graphs H₁,H₂, is the following implication true? If Independent Set parameterized by the requested set size k is fixed-parameter tractable on H₁-free graphs and is fixed-parameter tractable on H₂-free graphs, then it is fixed-parameter tractable on (H₁⊔H₂)-free graphs. Here exclusion is as an induced subgraph, ⊔ is disjoint union of the forbidden patterns, and fixed-parameter tractability has the deterministic meaning defined below. The two forbidden graphs may themselves be disconnected and may be isomorphic.',definitions='For a fixed graph H, an input to Independent Set on H-free graphs is a finite simple undirected graph G on n labeled vertices, encoded by its adjacency matrix, and a binary integer k with 0≤k≤n, under the promise that no subset of V(G) induces a graph isomorphic to H. The answer is YES exactly when there is a set S⊆V(G) with |S|≥k and no edge between distinct members of S. Only k is the parameter; H is fixed in the definition of the restricted problem and is not supplied as a variable-size input. Call H tractable if there exist a deterministic algorithm A_H, a total computable function f_H:ℕ→ℕ and a constant c_H≥0 such that A_H correctly decides every promised input in at most f_H(k)(n+1)^{c_H} bit operations. The algorithm is uniform over n,k and its guarantees are worst-case and exact. Behavior outside the H-free promise is unrestricted. Constants, algorithms and computable functions may depend on H, while c_H cannot depend on k or n. For H₁⊔H₂ take disjoint copies of their vertex sets, preserve the edges within each copy, and put no edges between copies. Thus a graph contains an induced H₁⊔H₂ precisely when it has disjoint induced copies of H₁ and H₂ with no cross-edge between them. Excluding this one disconnected pattern is weaker than simultaneously excluding both H₁ and H₂. The conjecture says that the set of tractable forbidden patterns is closed under ⊔. Its quantifier is over existence of algorithms for each fixed pair; it does not additionally demand one effective transformation that constructs an algorithm from descriptions of H₁,H₂ or from the two assumed algorithms. Input graphs G are not promised to be disconnected. Weighted Independent Set and randomized fixed-parameter algorithms define different variants; this card uses the source’s unqualified deterministic FPT convention.',question_type='yes_no',answer_criterion='Prove that for every fixed H₁,H₂ satisfying the two tractability premises there exist an algorithm A, a computable f and a constant c, all allowed to depend on that pair, deciding the (H₁⊔H₂)-free problem in f(k)(n+1)^c time; or refute this universal implication. A refutation must establish both premises and failure of the conclusion for its pair. A W[1]-hardness proof for the conclusion is only a conditional refutation unless the relevant FPT-versus-W[1] separation is assumed explicitly. A result for the intersection of the two graph classes or for disjoint input components does not settle this statement.',context_blocks=[dict(title='Combining forbidden patterns changes the input class',text='Every H₁-free or H₂-free input is automatically (H₁⊔H₂)-free, but the latter class can also contain both patterns. The conjecture asks whether this enlargement preserves parameterized tractability. It is not the elementary decomposition of Independent Set across disconnected input components.',citation='primary'),dict(title='The source proves an important special case',text='When the forbidden graph is a disjoint union of cliques, the paper gives an FPT algorithm. The concluding conjecture asks whether the same closure principle holds for all tractable forbidden patterns, not only clique components.',citation='journal'),dict(title='The expanded paper retains the conjecture',text='The author-hosted Algorithmica manuscript repeats the disjoint-union implication in its conclusion. It also distinguishes this question from another proposed closure operation, adding false twins, which the paper shows does not preserve the hoped-for tractability classification under the usual complexity separation.',citation='journal'),dict(title='Subsequent special-case progress has a randomness qualification',text='The ISAAC 2019 follow-up provides additional tractable forbidden patterns and randomized FPT algorithms for dart- and cricket-free graphs. These results concern individual patterns and do not prove the general disjoint-union implication. In particular, a randomized result is not silently substituted for the deterministic premises here.',citation='later')],why='A closure theorem would reduce the classification of parameterized Independent Set with one forbidden induced pattern to its connected components. It would organize many currently separate tractability results through one general structural principle.',references=refs,progress=[dict(date='2018',text='Work presented at IPEC 2018 proves the disjoint-clique special case and states the general disjoint-union conjecture; proceedings appeared 5 February 2019.',citation='primary'),dict(date='2019-11-28',text='ISAAC follow-up obtains more individual-pattern algorithms, including randomized dart- and cricket-free cases.',citation='later'),dict(date='2020-06-17',text='Journal version published; the expanded author manuscript retains the general closure conjecture.',citation='journal')],status='open',status_note='Read the original conjecture, induced-exclusion definition and parameter convention, the expanded journal manuscript’s conclusion, and the later ISAAC paper’s individual-pattern results and randomness qualification. Searched subsequent work without finding a resolution of the full closure implication. This is a source-grounded open status, not an exhaustive absence proof. No independent proof verification.',model_self_contained=True,requires_context=False,importance=dict(score=c['importance']['score'],method='editorial',reason='Would organize the parameterized complexity dichotomy for forbidden induced subgraphs by showing that disconnected obstructions introduce no new tractability barrier beyond their components. Existing score retained.',assessed_on=DATE),review_note='Recovered the universal closure implication, fixed-pattern quantifiers and deterministic FPT model; distinguished forbidding a union from forbidding both patterns.',working_summary=dict(sentences=['Independent Set asks whether a graph contains k pairwise nonadjacent vertices.','Suppose the problem is fixed-parameter tractable when either one of two fixed induced patterns is forbidden.','The conjecture asks whether tractability persists when only their disjoint union is forbidden.','This is already known when the forbidden components are cliques, and the 2020 journal manuscript retains the general conjecture.','The problem concerns the forbidden pattern, not whether the input graph itself is disconnected.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','journal','later'])),notes=['Defined deterministic FPT with k alone as parameter, fixed-pattern-dependent exponents and no uniform synthesis requirement.','Restored induced disjoint-union exclusion, including absent cross-edges; separated it from simultaneous forbidding and disconnected inputs.','Checked expanded 2020 conjecture and 2019 special cases, retaining randomized-versus-deterministic distinctions.','Corrected primary reference publication year to 2019 while preserving the 2018 conference origin.'],checked_sources=[r['url'] for r in refs]+['https://drops.dagstuhl.de/entities/document/10.4230/LIPIcs.IPEC.2018.17','https://doi.org/10.1007/s00453-022-01052-5'])
